# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE GENEL DEĞERLENDİRMESİ: İMAN VE İSLAM TEMEL KAVRAMLARI</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İman ve İslam İlişkisi</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• <tspan font-weight="bold">İman:</tspan> Kalp ile tasdik, dil ile ikrar.</text>\n  <text x="40" y="122" font-size="11.5" fill="#334155">• <tspan font-weight="bold">İslam:</tspan> Teslimiyet, barış ve</text>\n  <text x="48" y="140" font-size="11" fill="#475569">ibadetlerle imanı yaşamak.</text>\n  <text x="40" y="164" font-size="11.5" fill="#334155">• <tspan font-weight="bold">İhsan:</tspan> Allah\'ı görüyormuş</text>\n  <text x="48" y="182" font-size="11" fill="#475569">gibi bilinçli kulluk yapmak.</text>\n  <text x="130" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">İman + Salih Amel = Güzel Ahlak</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İmanın Şartları (6 Esas)</text>\n  <text x="260" y="98" font-size="11.5" fill="#334155">1. Allah\'ın varlığı ve birliğine (Tevhid)</text>\n  <text x="260" y="120" font-size="11.5" fill="#334155">2. Meleklerine iman</text>\n  <text x="260" y="142" font-size="11.5" fill="#334155">3. İlahi kitaplarına iman</text>\n  <text x="260" y="164" font-size="11.5" fill="#334155">4. Peygamberlerine iman</text>\n  <text x="260" y="186" font-size="11.5" fill="#334155">5. Ahiret gününe iman</text>\n  <text x="260" y="208" font-size="11.5" fill="#334155">6. Kader ve kazaya iman</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Esmâ-i Hüsnâ (Güzel İsimler)</text>\n  <text x="480" y="100" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">El-Hâdî:</tspan> Doğru yolu gösteren,</text>\n  <text x="488" y="118" font-size="11" fill="#475569">hidayete ulaştıran.</text>\n  <text x="480" y="144" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Es-Selâm:</tspan> Esenlik, barış ve</text>\n  <text x="488" y="162" font-size="11" fill="#475569">güven kaynağı olan.</text>\n  <text x="480" y="188" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">El-Vekîl:</tspan> Tevekkül edilen, işleri</text>\n  <text x="488" y="206" font-size="11" fill="#475569">en güzel yoluna koyan.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTEYE GİRİŞ: İSLAM AHLAKININ KAYNAKLARI</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Temel Kaynak: Kur\'an-ı Kerim</text>\n  <text x="48" y="104" font-size="11.5" fill="#334155">• İyi ile kötüyü, doğru ile yanlışı ayırt eden</text>\n  <text x="58" y="122" font-size="11.5" font-weight="bold" fill="#1e40af">el-Furkan</text>\n  <text x="115" y="122" font-size="11.5" fill="#334155">ve ilahi rehberdir.</text>\n  <text x="48" y="148" font-size="11.5" fill="#334155">• Adaleti, iyiliği (ihsanı), anne babaya</text>\n  <text x="58" y="166" font-size="11" fill="#475569">hürmeti, doğruluğu ve yardımlaşmayı emreder.</text>\n  <text x="48" y="192" font-size="11.5" fill="#334155">• Yalan, gıybet, iftira, kibir ve israf gibi</text>\n  <text x="58" y="210" font-size="11" fill="#475569">kötü huyları kesin olarak yasaklar.</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Canlı Örnek: Hz. Peygamber\'in Sünneti</text>\n  <text x="378" y="104" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Üsve-i Hasene:</tspan> En güzel örnek (Ahzâb, 21).</text>\n  <text x="378" y="128" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Huluk-u Azîm:</tspan> Yüce bir ahlak (Kalem, 4).</text>\n  <text x="378" y="154" font-size="11" font-weight="bold" fill="#15803d">• &quot;Ben güzel ahlakı tamamlamak için gönderildim.&quot;</text>\n  <text x="378" y="180" font-size="11.5" fill="#334155">• Hz. Âişe\'nin ifadesiyle Peygamberimizin</text>\n  <text x="388" y="198" font-size="11.5" font-weight="bold" fill="#166534">&quot;ahlakı Kur\'an ahlakıdır&quot;</text>\n  <text x="388" y="216" font-size="11" fill="#475569">(yaşayan Kur\'an).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AHLAK-TERBİYE İLİŞKİSİ VE GÜZEL AHLAK (AHLAK-I HAMÎDE) İLKELERİ</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ahlak, Huy (Hulk) ve Terbiye</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Ahlak (Hulk):</tspan> İnsanda yerleşmiş olan</text>\n  <text x="58" y="120" font-size="11" fill="#475569">karakter, mizaç ve iradeli davranış biçimleri.</text>\n  <text x="48" y="146" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Terbiye:</tspan> İnsanın ruhunu ve davranışlarını</text>\n  <text x="58" y="164" font-size="11" fill="#475569">eğiterek güzelleştirme, yetiştirme süreci.</text>\n  <text x="48" y="190" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Ahlak-ı Hamîde:</tspan> Övülen güzel ahlak.</text>\n  <text x="48" y="212" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#b91c1c">Ahlak-ı Zemîme:</tspan> Yerilen kötü huylar.</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temel Güzel Ahlak İlkeleri</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Sıdk ve Emanet:</tspan> Doğruluk ve güvenilirlik</text>\n  <text x="378" y="126" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Adalet ve Merhamet:</tspan> Hakkaniyet ve şefkat</text>\n  <text x="378" y="150" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Tevazu ve Sabır:</tspan> Alçakgönüllülük ve direnç</text>\n  <text x="378" y="174" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Cömertlik ve İnfak:</tspan> Paylaşma ve yardımlaşma</text>\n  <text x="378" y="198" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Edep ve Hayâ:</tspan> Utanma duygusu ve nezaket</text>\n  <text x="515" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">İman, ibadet ve güzel ahlak ayrılmaz bir bütündür!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
